public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends log file for a call to Telegram servers
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SendCallLogAsync(InputCall callId = default, InputFile logFile = default)
    {

           using var activity =  StartCallActivity("SendCallLogAsync", typeof(SendCallLog).FullName ?? "SendCallLogAsync");

           try
           {
             return client.SendCallLogAsync(callId, logFile);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
